//! Compares the sanitizer / injection detector against outputs recorded from the python
//! implementation (tests/fixtures/sanitizer_cases.json, generated by running the python
//! PromptInjectionDetector / ContentSanitizer classes on a fixed corpus).

use ol_modules_web::sanitize::{ContentSanitizer, PromptInjectionDetector};
use serde_json::Value;

fn fixture() -> Value {
    serde_json::from_str(include_str!("fixtures/sanitizer_cases.json")).unwrap()
}

#[test]
fn sanitizer_matches_python() {
    let f = fixture();
    let mut failures = Vec::new();
    for case in f["cases"].as_array().unwrap() {
        let input = case["input"].as_str().unwrap();
        for (key, got) in [
            ("sanitize", ContentSanitizer::sanitize(input)),
            ("sanitize_remove", ContentSanitizer::sanitize_mode(input, "remove")),
            ("sanitize_html", ContentSanitizer::sanitize_html_content(input)),
        ] {
            if case[key].as_str().unwrap() != got {
                failures.push(format!("{} {:?}\n  python: {:?}\n  rust:   {:?}", key, input, case[key].as_str().unwrap(), got));
            }
        }
        let d = PromptInjectionDetector::detect_injection(input);
        let mut pats = d.patterns_found.clone();
        pats.sort();
        let exp = &case["detect"];
        let exp_pats: Vec<String> = exp["patterns"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect();
        let exp_ev: Vec<String> = exp["evidence"].as_array().unwrap().iter().map(|v| v.as_str().unwrap().to_string()).collect();
        if pats != exp_pats || d.risk_level != exp["risk_level"].as_str().unwrap() || d.is_malicious != exp["is_malicious"].as_bool().unwrap() || d.evidence != exp_ev {
            failures.push(format!("detect {:?}\n  python: {} \n  rust:   {:?} {:?} {:?}", input, exp, d.risk_level, pats, d.evidence));
        }
    }
    for s in f["structured"].as_array().unwrap() {
        let got = ContentSanitizer::sanitize_structured_data(&s["input"]);
        if got != s["output"] {
            failures.push(format!("structured {}\n  python: {}\n  rust:   {}", s["input"], s["output"], got));
        }
    }
    assert!(failures.is_empty(), "{} mismatches:\n{}", failures.len(), failures.join("\n"));
}
